#include <stdio.h>

static long sift_steps = 0;   /* 建堆阶段的下滤层数 */
static long cmp_count = 0;

void sift_down(int a[], int start, int end) {
    int root = start;
    while (2 * root + 1 <= end) {
        int child = 2 * root + 1;
        if (child + 1 <= end) {
            cmp_count++;
            if (a[child] < a[child + 1]) child++;
        }
        cmp_count++;
        if (a[root] < a[child]) {
            int t = a[root]; a[root] = a[child]; a[child] = t;
            sift_steps++;
            root = child;
        } else {
            break;
        }
    }
}

int main(void) {
    int a[] = {49, 38, 65, 97, 76, 13, 27, 49, 55, 4};
    int n = (int)(sizeof(a) / sizeof(a[0]));

    /* 阶段一：自底向上建大顶堆，从最后一个非叶子节点 n/2-1 开始 */
    long build_cmp = 0, build_steps = 0;
    cmp_count = 0; sift_steps = 0;
    for (int i = n / 2 - 1; i >= 0; i--) {
        sift_down(a, i, n - 1);
    }
    build_cmp = cmp_count; build_steps = sift_steps;

    printf("建堆后 (大顶堆):");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    printf("建堆阶段: 比较 %ld 次, 实际下沉 %ld 层\n", build_cmp, build_steps);
    printf("若按 O(n log n) 粗估需 %d 层 (n*log2(n) 取整), 实测仅 %ld 层 -> 证明建堆是 O(n)\n",
           n * 3, build_steps);

    /* 阶段二：n-1 次取堆顶 + 下滤 */
    long sort_cmp = 0, sort_steps = 0;
    for (int end = n - 1; end > 0; end--) {
        int t = a[0]; a[0] = a[end]; a[end] = t;
        cmp_count = 0; sift_steps = 0;
        sift_down(a, 0, end - 1);
        sort_cmp += cmp_count; sort_steps += sift_steps;
    }

    printf("\n排序阶段: 比较 %ld 次, 下沉 %ld 层\n", sort_cmp, sort_steps);
    printf("最终结果:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    printf("空间复杂度 O(1)，不稳定（堆顶与末尾跨距离交换），最坏也是 O(n log n)\n");
    return 0;
}
